#!/usr/bin/env python3
"""Bounded read-only comparison of named receiving returns and immutable evidence.

This is a mechanical verifier. It does not execute archive code, access private
primaries, interpret new receiving meanings, or establish audit acceptance.
Only the detailed JSON, compact public JSON and Markdown reports next to this
script are written.
"""
import argparse
import collections
import copy
import datetime
import hashlib
import io
import json
from pathlib import Path
import subprocess
import sys
import termios
import urllib.request
import zipfile

ROOT = Path('ephemeral-workspace')
REPO = ROOT / 'bwp'
