INPUT_PATH = 'docs/research/implementaudit/r003f-r0041-preparation-inputs.json'
PINS = {
    'projection': (REPO / PROJ_PATH, 4713015, 'c748438a378aea18c28a17c4ae5f584993498355c81d00f1e6327c41ac8d4f42'),
    'inputs': (REPO / INPUT_PATH, 177033, '1711dc1ca08f41ee1560b0c5162f14d6dabdff668cae91b7e704fa251b7146bd'),
    'ebpm': (RUN / 'ebpm-preparation-return.json', 1262105, 'f666ce9b9caa57a27d769e8607f12da1ce32f4d8195619dd5bf86d57020f163d'),
    'ewm': (RUN / 'ewm-preparation-return.json', 1062491, 'c8b0845afad5fb6e669520d563be202c952677cfb6d480a5f8b6fbfe86f1b30e'),
    'embedded_member_context_partial': (RUN / 'embedded-bwp-member-context-partial.json', 2221649, '03d6d5529a0f548740ab9e2c53f0d6df4071e63723d1f1e9d3fd53e81e881cd0'),
    'embedded_group_case': (RUN / 'embedded-bwp-group-case-return.json', 544558, '9399616c92170e7d44a151c24c59507bdcc0c6a8c50380a9b71409aed714de94'),
}
MISSING = object()
checks = []
sources = []
limitations = [
    'Mechanical comparison only. No new source/content/meaning receiving episode, acceptance, review disposition, authority, currentness, publication, release, or closure is established.',
    'Exact public normalized qualification content is hashed in full. Original context hashes from excluded private primaries are preserved identity labels and are not independently recomputed.',
