    'Nonempty judgment fields are structural presence observations only. Their meaning, sufficiency, and actual semantic reading are not mechanically certified.',
    'A source file unavailable at a08 is not declared absent from its separately pinned original public commit.',
]
supplied_target_bytes = None
access_notes = []
checker_observations = [
    {'stage': 'preliminary component extension', 'observation': "An initial checker mapping assumed that all source groups contain the many-to-one field 'distinction'. BWP-K034 is a one-to-many group with a different complete field set. That run stopped with KeyError before writing a new report. The mapping now compares every actual original field except members, distinct_mechanisms and relation_ids; memberships are checked separately, and omitted full-source fields remain covered by the full-record binding/hash. No receiving data were changed and this was not classified as malformed receiving content."},
]


def canonical(x):
    return json.dumps(x, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')


def sha(b):
    return hashlib.sha256(b).hexdigest()


def digest(x):
    return sha(canonical(x))


def at(obj, pointer):
    try:
        if pointer == '':
            return obj
        if not isinstance(pointer, str) or not pointer.startswith('/'):
            return MISSING
        for part in pointer[1:].split('/'):
            part = part.replace('~1', '/').replace('~0', '~')
            obj = obj[int(part)] if isinstance(obj, list) else obj[part]
        return obj
    except (KeyError, IndexError, TypeError, ValueError):
        return MISSING


def summary(value):
    if value is MISSING:
        return {'present': False}
    if isinstance(value, (dict, list)):
        return {'type': type(value).__name__, 'length': len(value), 'canonical_sha256': digest(value)}
    return value


def compare(section, subject, field, actual, expected, evidence=None):
    if actual is MISSING or expected is MISSING:
        status = 'MISSING_COMPARISON_VALUE'
    else:
        try:
            status = 'MATCH' if canonical(actual) == canonical(expected) else 'MISMATCH'
        except (ValueError, TypeError) as exc:
            status = 'MALFORMED_COMPARISON_VALUE'
            evidence = {'original_evidence': evidence, 'error': repr(exc)}
    entry = {'section': section, 'subject': subject, 'field': field, 'status': status,
             'actual': summary(actual), 'expected': summary(expected)}
    if evidence is not None:
        entry['evidence'] = evidence
    if status != 'MATCH':
        entry['actual_complete'] = {'absent': True} if actual is MISSING else actual
        entry['expected_complete'] = {'absent': True} if expected is MISSING else expected
    checks.append(entry)
    return status == 'MATCH'


def problem(section, subject, field, status, detail):
    checks.append({'section': section, 'subject': subject, 'field': field, 'status': status, 'detail': detail})


def parse(raw, subject):
    duplicate_names = []
    def pairs_hook(pairs):
        out = {}
        for key, value in pairs:
            if key in out:
                duplicate_names.append(key)
            out[key] = value
        return out
    try:
        value = json.loads(raw, object_pairs_hook=pairs_hook)
    except (ValueError, UnicodeDecodeError) as exc:
        problem('file_integrity', subject, 'json_parse', 'MALFORMED_JSON', repr(exc))
        return None
    compare('file_integrity', subject, 'duplicate_object_keys', duplicate_names, [])
    return value


def record_bytes(subject, raw, expected_bytes=None, expected_sha=None, route=None):
    result = {'subject': subject, 'bytes': len(raw), 'sha256': sha(raw)}
    if route is not None:
        result['route'] = route
    sources.append(result)
    if expected_bytes is not None:
        compare('file_integrity', subject, 'bytes', len(raw), expected_bytes)
    if expected_sha is not None:
        compare('file_integrity', subject, 'sha256', sha(raw), expected_sha)
    return result


def local_json(subject, path, n, h):
    try:
        raw = path.read_bytes()
    except OSError as exc:
        problem('file_integrity', subject, 'read', 'MISSING_SOURCE', repr(exc))
        return None
    record_bytes(subject, raw, n, h, str(path))
    return parse(raw, subject)


def remove_annotations(value):
    if isinstance(value, dict):
        return {k: remove_annotations(v) for k, v in value.items() if not k.startswith('__published_identity_')}
    if isinstance(value, list):
        return [remove_annotations(v) for v in value]
    return value


def keyed(rows, key, section, subject, expected_keys=None):
    if not isinstance(rows, list):
        problem(section, subject, 'rows', 'MALFORMED_POPULATION', {'expected': 'list', 'actual': summary(rows)})
        return {}
    values = [row.get(key, MISSING) if isinstance(row, dict) else MISSING for row in rows]
    valid = [v for v in values if isinstance(v, str)]
    compare(section, subject, 'missing_or_nonstring_keys', len(values) - len(valid), 0)
    duplicates = {k: n for k, n in collections.Counter(valid).items() if n > 1}
    compare(section, subject, 'duplicate_keys', duplicates, {})
    if expected_keys is not None:
        compare(section, subject, 'keyed_population', sorted(valid), sorted(expected_keys))
    return {row[key]: row for row in rows if isinstance(row, dict) and isinstance(row.get(key), str)}


def present(section, subject, obj, fields):
    for field in fields:
        val = at(obj, field)
        compare(section, subject, field + ':nonempty', val is not MISSING and val not in ('', None, [], {}), True)


def apply_patches(base, patches):
    value = copy.deepcopy(base)
    for op in patches:
        parts = op['path'].split('/')[1:]
        parts = [x.replace('~1', '/').replace('~0', '~') for x in parts]
        parent = value
        for token in parts[:-1]:
            parent = parent[int(token)] if isinstance(parent, list) else parent[token]
        token = parts[-1]
        if isinstance(parent, list):
            index = len(parent) if token == '-' else int(token)
            if op['op'] == 'remove':
                del parent[index]
            elif op['op'] == 'replace':
                parent[index] = copy.deepcopy(op['value'])
            elif op['op'] == 'add':
                parent.insert(index, copy.deepcopy(op['value']))
            else:
                raise ValueError('unsupported patch operation: ' + op['op'])
        elif op['op'] == 'remove':
            del parent[token]
        elif op['op'] == 'replace':
            if token not in parent:
                raise KeyError(token)
            parent[token] = copy.deepcopy(op['value'])
        elif op['op'] == 'add':
            parent[token] = copy.deepcopy(op['value'])
        else:
            raise ValueError('unsupported patch operation: ' + op['op'])
    return value


def load_public_sources(projection, inputs):
    carriers = {}
    bindings = []
    for p in projection['properties']:
        bindings.extend(p[k] for k in ('full_original_record_binding', 'full_bwp_source_record_binding', 'full_corrected_target_disposition_binding'))
    bindings.extend(g['full_original_group_record_binding'] for g in projection['groups'])
    pins = {b['published_a08_binding_record']['path']: b['published_a08_binding_record'] for b in bindings}
    for path, pin in sorted(pins.items()):
        result = subprocess.run(['git', 'show', A08 + ':' + path], cwd=REPO, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode:
            problem('public_source', path, 'git_show', 'MISSING_LOCAL_A08_CARRIER', result.stderr.decode('utf-8', 'replace'))
            continue
        record_bytes('a08:' + path, result.stdout, pin['bytes'], pin['sha256'], A08 + ':' + path)
        carriers[path] = parse(result.stdout, 'a08:' + path)
    zip_path = OUT / 'public-frozen/EVOLVED_BWP_FROZEN_PACKET.zip'
    archive_raw = zip_path.read_bytes()
    pin = inputs['public_frozen_packet']
    record_bytes('public_frozen_zip', archive_raw, pin['bytes'], pin['sha256'], {'cache': str(zip_path), 'immutable_url': pin['url']})
    compare('file_integrity', 'public_frozen_zip', 'git_blob', sha_git_blob(archive_raw), pin['git_blob'])
    archive = zipfile.ZipFile(io.BytesIO(archive_raw))
    loaded = {}
    wanted = {x['path'].split('/')[-1]: x for x in projection['source_locator_resolution']['original_lineage_ledgers'].values()}
    for name in ('EVOLVED_BWP_INTER_CROSSWALK_INTAKE.json', 'EVOLVED_BWP_CONVERGENCE_AND_COMPOSITION_CLUSTERS.json', 'EVOLVED_BWP_DIRECTIONAL_RELATION_LEDGER.json'):
        wanted[name] = projection['source_locator_resolution']['bwp_archive_members'][name]
    for basename, pin in wanted.items():
        routes = [x for x in archive.namelist() if x.split('/')[-1] == basename]
        compare('public_source', basename, 'unique_archive_member_route', len(routes), 1)
        if len(routes) != 1:
            continue
        raw = archive.read(routes[0])
        record_bytes('archive:' + routes[0], raw, pin['bytes'], pin['sha256'], {'archive_sha256': sha(archive_raw), 'member': routes[0]})
        loaded[basename] = parse(raw, 'archive:' + routes[0])
    target_pin = projection['source_locator_resolution']['corrected_historical_target']
    target = None
    try:
        if supplied_target_bytes is not None:
            raw = supplied_target_bytes
            acquisition = {'immutable_url': target_pin['url'], 'method': 'Read-only GitHub fetch_blob, supplied through JSON-lines stdin without a source-cache write', 'git_blob': '5e94bd9c4f899aa3cbc11fe7da8698620f379e8d'}
            compare('file_integrity', 'corrected_historical_target', 'git_blob', sha_git_blob(raw), acquisition['git_blob'])
        else:
            with urllib.request.urlopen(target_pin['url'], timeout=30) as response:
                raw = response.read()
            acquisition = target_pin['url']
        record_bytes('corrected_historical_target', raw, target_pin['bytes'], target_pin['sha256'], acquisition)
        if len(raw) == target_pin['bytes'] and sha(raw) == target_pin['sha256']:
            target = parse(raw, 'corrected_historical_target')
        else:
            problem('public_source', 'corrected_historical_target', 'use', 'UNTRUSTED_IDENTITY', 'Fetched bytes do not match the frozen pin; not used for comparison.')
    except Exception as exc:
        problem('public_source', 'corrected_historical_target', 'https_fetch', 'UNAVAILABLE_SOURCE', repr(exc))
        limitations.append('Exact corrected historical target fetch unavailable; historical dispositions use the exact a08 bound carrier, and target full-record hash comparison is recorded as unavailable.')
    return carriers, loaded, target


def sha_git_blob(raw):
    return hashlib.sha1(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest()


def source_objects(projection, carriers, loaded, target):
    originals = {}
    historical = {}
    intake = loaded['EVOLVED_BWP_INTER_CROSSWALK_INTAKE.json']
    for prop in projection['properties']:
        key = prop['key']
        lin = key.split(':')[0]
        original_name = projection['source_locator_resolution']['original_lineage_ledgers'][lin]['path'].split('/')[-1]
        original = at(loaded[original_name], prop['full_original_record_binding']['public_source_record']['pointer'])
        originals[key] = original
        source = at(intake, prop['full_bwp_source_record_binding']['public_source_record']['pointer'])
        target_pointer = prop['full_corrected_target_disposition_binding']['public_source_record']['pointer']
        target_record = at(target, target_pointer) if target is not None else MISSING
        if target_record is not MISSING:
            historical[key] = target_record
        else:
            binding = prop['full_corrected_target_disposition_binding']['published_a08_binding_record']
            carrier = carriers.get(binding['path'], {})
            row = at(carrier, '/'.join(binding['pointer'].split('/')[:3]))
            historical[key] = row.get('historical_target', {}).get('full_record', row.get('prepared_target_meaning', {})) if isinstance(row, dict) else {}
        section = 'projection_source_bindings'
        compare(section, key, 'original_global_identity', lin + ':' + original.get('PROPERTY_ID', ''), key)
        compare(section, key, 'original_name', prop['name'], original.get('PROPERTY_NAME', MISSING))
        compare(section, key, 'source_intake_key', source.get('key', MISSING), key)
        compare(section, key, 'source_intake_source_status', source.get('disposition', MISSING), original.get('CURRENT_STATUS', MISSING))
        compare(section, key, 'original_hash', digest(original), prop['full_original_record_binding']['canonical_record_sha256'])
        compare(section, key, 'preparation_original_record_hash', prop['original_property']['record_sha256'], digest(original))
        compare(section, key, 'intake_hash', digest(source), prop['full_bwp_source_record_binding']['canonical_record_sha256'])
        if target_record is not MISSING:
            compare(section, key, 'historical_target_key', target_record.get('key', MISSING), key)
            compare(section, key, 'historical_target_full_hash', digest(target_record), prop['full_corrected_target_disposition_binding']['canonical_record_sha256'])
        else:
            problem(section, key, 'historical_target_full_hash', 'NOT_CHECKED_UNAVAILABLE_SOURCE', {'pointer': target_pointer, 'binding': prop['full_corrected_target_disposition_binding']})
        for field, orig_field in [('reason/source', 'DISPOSITION_RATIONALE'), ('first_missing_discriminator/source_transfer_test', 'ASSUMPTION_SENSITIVITY'), ('first_missing_discriminator/observable_postcondition', 'OBSERVABLE_POSTCONDITION'), ('reconsideration_trigger/source_trigger', 'TRIGGER_OR_CONTEXT'), ('reconsideration_trigger/nontrigger', 'NON_TRIGGER_OR_CHEAP_PATH')]:
            compare(section, key, field, at(prop, '/' + field), original.get(orig_field, MISSING))
        for field, target_field in [('reason/target', 'rationale'), ('reason/qualification_limit', 'qualification_limit'), ('first_missing_discriminator/target_delta', 'required_delta')]:
            compare(section, key, field, at(prop, '/' + field), historical[key].get(target_field, MISSING))
        compare(section, key, 'ordered_group_ids', prop['group_ids'], source.get('cluster_ids', MISSING))
        compare(section, key, 'ordered_relation_ids', prop['relation_ids'], source.get('BWP_relation_ids', MISSING))
        for binding_name in ('full_original_record_binding', 'full_bwp_source_record_binding', 'full_corrected_target_disposition_binding'):
            binding = prop[binding_name]
            pin = binding['published_a08_binding_record']
            bound = at(carriers.get(pin['path'], {}), pin['pointer'])
            bound_hash = bound.get('canonical_record_sha256', bound.get('canonical_sha256', MISSING)) if isinstance(bound, dict) else MISSING
            compare(section, key, binding_name + ':a08_record_hash', bound_hash, binding['canonical_record_sha256'], pin)
            compare(section, key, binding_name + ':a08_record_pointer', bound.get('pointer', MISSING) if isinstance(bound, dict) else MISSING, binding['public_source_record']['pointer'])
    return originals, historical


def projection_integrity(projection, inputs, carriers, loaded):
    props = keyed(projection['properties'], 'key', 'projection', 'members')
    groups = keyed(projection['groups'], 'group_id', 'projection', 'groups')
    compare('projection', 'population', 'lineages', dict(collections.Counter(k.split(':')[0] for k in props)), {k: projection['population'][k] for k in ('EBPM', 'EPM', 'EWM')})
    compare('projection', 'population', 'members', len(props), 234)
    compare('projection', 'population', 'groups', len(groups), 41)
    compare('projection', 'population', 'memberships', sum(len(g['member_original_property_identities']) for g in groups.values()), 608)
    for lin in ('EBPM', 'EPM', 'EWM'):
        counts = dict(collections.Counter(p['absorption_state'] for p in props.values() if p['key'].startswith(lin + ':')))
        compare('projection', lin, 'per_member_preparation_counts', counts, projection['preparation_state_counts'][lin])
    source_clusters = loaded['EVOLVED_BWP_CONVERGENCE_AND_COMPOSITION_CLUSTERS.json']
    for key, group in groups.items():
        binding = group['full_original_group_record_binding']
        orig = at(source_clusters, binding['public_source_record']['pointer'])
        compare('projection_group_integrity', key, 'source_group_id', orig.get('id', MISSING), key)
        compare('projection_group_integrity', key, 'full_original_group_hash', digest(orig), binding['canonical_record_sha256'])
        compare('projection_group_integrity', key, 'ordered_members', group['member_original_property_identities'], orig.get('members', MISSING))
        compare('projection_group_integrity', key, 'name', group['name'], orig.get('name', MISSING))
        compare('projection_group_integrity', key, 'no_duplicate_members', len(set(group['member_original_property_identities'])), len(group['member_original_property_identities']))
        expected_states = {m: props[m]['absorption_state'] for m in group['member_original_property_identities'] if m in props}
        compare('projection_group_integrity', key, 'full_member_state_map', group['member_absorption_states'], expected_states)
        compare('projection_group_integrity', key, 'member_state_counts', group['member_absorption_counts'], dict(collections.Counter(expected_states.values())))
        compare('projection_group_integrity', key, 'group_state_retained_as_group_state', group['absorption_state'], 'PARTIALLY_ABSORBED')
        compare('projection_group_integrity', key, 'material_relation_declared_count', group['material_relations']['count'], len(group['material_relations']['record_ids']))
        pin = binding['published_a08_binding_record']
        original_binding = at(carriers[pin['path']], pin['pointer'])
        compare('projection_group_integrity', key, 'a08_full_original_group_hash', original_binding.get('canonical_record_sha256', MISSING), binding['canonical_record_sha256'])
    for key, prop in props.items():
        inverse = [g['group_id'] for g in projection['groups'] if key in g['member_original_property_identities']]
        compare('projection_inverse_membership', key, 'ordered_group_ids', prop['group_ids'], inverse)
    expected_occurrences = []
    for index, prop in enumerate(projection['properties']):
        for occurrence_index, ref in enumerate(prop['first_missing_discriminator']['receiving_qualification']):
            expected_occurrences.append({'property_key': prop['key'], 'property_pointer': '/properties/' + str(index), 'occurrence_index': occurrence_index, 'original_occurrence_pointer': f'/properties/{index}/first_missing_discriminator/receiving_qualification/{occurrence_index}', 'context_sha256': ref['context_sha256'], 'context_pointer': ref['context_pointer']})
    compare('projection_context_integrity', 'all', 'ordered_occurrences', projection['qualification_occurrences'], expected_occurrences)
    compare('projection_context_integrity', 'all', 'occurrence_count', len(expected_occurrences), 353)
    compare('projection_context_integrity', 'all', 'context_count', len(projection['qualification_contexts']), 31)
    for key, context in projection['qualification_contexts'].items():
        compare('projection_context_integrity', key, 'original_identity_label', context['original_context_sha256'], key)
        compare('projection_context_integrity', key, 'full_public_content_hash', digest(context['content']), context['public_projection_sha256'])
        compare('projection_context_integrity', key, 'full_field_count', len(context['content']), 20)
        compare('projection_context_integrity', key, 'historical_behavior_pass', context['content']['behavior_pass_from_this_join'], False)
    compare('projection', 'canonical', 'without_identity_annotations', digest(remove_annotations(projection)), inputs['complete_preparation_projection']['canonical_sha256_without_identity_annotations'])
    return props, groups


def cases_integrity(section, report_rows, inputs, projection, mode='ebpm'):
    expected = {c['case_id']: c for c in inputs['cases']}
    rows = keyed(report_rows, 'case_id', section, 'cases', expected)
    canonical_projection = remove_annotations(projection)
    for key, case in expected.items():
        try:
            derived_hash = digest(apply_patches(canonical_projection, case['carrier_patches']))
            compare('input_case_derivation', key, 'canonical_derived_hash', derived_hash, case['derived_carrier_canonical_sha256'])
        except Exception as exc:
            problem('input_case_derivation', key, 'patch_application', 'MALFORMED_PATCH', repr(exc))
            continue
        if key not in rows:
            continue
        ret = rows[key]
        compare(section, key, 'title', ret.get('title', MISSING), case['title'])
        if 'declared_applicable_scopes' in ret:
            compare(section, key, 'declared_applicable_scopes', ret['declared_applicable_scopes'], case['applicable_scopes'])
        if mode == 'ebpm' and 'actual_input_basis' in ret:
            basis = ret['actual_input_basis']
            for field, exp in [('input_path', INPUT_PATH), ('input_pointer', '/cases/' + str(inputs['cases'].index(case))), ('input_sha256', PINS['inputs'][2]), ('projection_sha256', PINS['projection'][2]), ('patch_operations_applied_in_declared_order', len(case['carrier_patches'])), ('derived_canonical_sha256', derived_hash), ('derived_hash_verified', True)]:
                compare(section, key, 'actual_input_basis/' + field, basis.get(field, MISSING), exp)
        if mode == 'ewm':
            for field, exp in [('input_path', INPUT_PATH), ('input_sha256', PINS['inputs'][2]), ('input_pointer', '/cases/' + str(inputs['cases'].index(case))), ('proposal_received_as_data', case['proposal_to_assess']), ('actual_evidence_class', case['evidence_class'])]:
                compare(section, key, field, ret.get(field, MISSING), exp)
            for field, exp in [('base_canonical_sha256', digest(canonical_projection)), ('operation_count', len(case['carrier_patches'])), ('applied_in_declared_order', True), ('expected_derived_sha256', derived_hash), ('actual_derived_sha256', derived_hash), ('matches', True), ('native_execution', False)]:
                compare(section, key, 'overlay_verification/' + field, at(ret, '/overlay_verification/' + field), exp)
            present(section, key, ret, ['/decision', '/supported_premise', '/unsupported_step', '/reasoning', '/preserved_alternative', '/material_residual', '/next_action'])
        elif mode == 'component':
            compare(section, key, 'input_pointer', ret.get('input_pointer', MISSING), '/cases/' + str(inputs['cases'].index(case)))
            compare(section, key, 'applicable_scopes_in_input', ret.get('applicable_scopes_in_input', MISSING), case['applicable_scopes'])
            compare(section, key, 'evidence_class', ret.get('evidence_class', MISSING), case['evidence_class'])
            for field, exp in [('operations', len(case['carrier_patches'])), ('applied_in_declared_order', True), ('identity_annotations_stripped_only', True), ('derived_canonical_sha256', derived_hash), ('expected_canonical_sha256', derived_hash), ('match', True)]:
                compare(section, key, 'ordered_overlay/' + field, at(ret, '/ordered_overlay/' + field), exp)
            present(section, key, ret, ['/decision', '/actual_input_basis', '/supported_clauses', '/unsupported_clauses', '/kept_alternatives', '/next_action', '/scope_ceiling'])
        else:
            present(section, key, ret, ['/actual_outcome', '/evidence_class'])


def check_contexts(section, rows, projection, scope_keys, embedded=False):
    relevant = [o for o in projection['qualification_occurrences'] if o['property_key'] in scope_keys]
    expected_keys = sorted({o['context_sha256'] for o in relevant})
    mapped = keyed(rows, 'context_key' if embedded else 'original_context_sha256', section, 'contexts', expected_keys)
    for key, ret in mapped.items():
        if key not in projection['qualification_contexts']:
            continue
        context = projection['qualification_contexts'][key]
        body = context['content']
        compare(section, key, 'original_context_identity', ret.get('original_context_sha256', MISSING), key)
        compare(section, key, 'full_public_content_hash', ret.get('public_projection_sha256', MISSING), digest(body))
        compare(section, key, 'full_content_pointer', ret.get('full_content_pointer' if embedded else 'pointer', MISSING), '/qualification_contexts/' + key + '/content')
        occurrences = [o for o in relevant if o['context_sha256'] == key]
        compare(section, key, 'ordered_complete_occurrences', ret.get('ordered_occurrences' if embedded else 'occurrences', MISSING), occurrences)
        compare(section, key, 'occurrence_count', ret.get('occurrence_count', MISSING), len(occurrences))
        mapping = {'concern': 'concern', 'historical_returned_disposition': 'returned_disposition', 'historical_decision_branch': 'decision_branch'}
        if embedded:
            mapping.update({'slice': 'slice', 'preserved_positive_negative_boundary_stimulus': 'first_missing_stimulus'})
        else:
            mapping.update({'source_contract_scope': 'source_contract_scope', 'trigger': 'trigger', 'no_source_delta_or_nontrigger': 'no_source_delta_or_nontrigger', 'first_missing_stimulus_preserved': 'first_missing_stimulus', 'source_epoch_preserved': 'source_epoch', 'behavior_pass_from_this_join': 'behavior_pass_from_this_join'})
        for actual_field, expected_field in mapping.items():
            compare(section, key, actual_field, ret.get(actual_field, MISSING), body.get(expected_field, MISSING))
        present(section, key, ret, ['/current_receiving_judgment'])
    return {'contexts': len(mapped), 'occurrences': len(relevant), 'keys': sorted(mapped)}


def check_manifest(name, report, projection, inputs):
